{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Erlotinib, the closest analogue by Morgan similarity and a kinase inhibitor with the same anilino-heteroaromatic motif, has absolute oral bioavailability of 59% (95% CI 55-63%) in healthy subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Tramadol, which shares the methoxyphenyl and amino-alcohol/piperidine-like features, has mean absolute oral bioavailability of 67.9% in adult volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "AZD5423, a methoxyphenyl-containing compound, has oral bioavailability of only 4.4%, providing a low-F counterexample; however, it is an inhaled drug with intentionally low oral bioavailability and lower structural transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C37"],
      "claim": "A methoxyphenyl-piperidine-benzimidazole analogue has absolute oral bioavailability of 3% in humans, a low-F counterexample.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most relevant analogues (erlotinib, simotinib, tramadol) show oral bioavailability well above 20%, and the query's anilino-heteroaromatic kinase-inhibitor scaffold is consistent with oral absorption. Low-F analogues are either inhaled drugs with intentionally low oral bioavailability or structurally distant compounds with specific first-pass liabilities. Therefore, high F is better supported.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.25), limiting transferability.",
    "No information on the query's metabolic stability, efflux liability, or solubility.",
    "Mixed low-F counterexamples remain, but they are structurally and mechanistically less relevant."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

